var cfg=UnityEditor.AssetDatabase.LoadAssetAtPath<Lighthouse.World.MapGeneration.Rules.MapGenerationConfig>("Assets/02.Prefabs/World/Data/MapGeneration/MapGenerationConfig.asset");
var assets=new[]{cfg.LighthouseIsland}.Concat(cfg.Archetypes).Distinct().ToArray();
var deps=UnityEditor.AssetDatabase.GetDependencies(assets.Select(a=>UnityEditor.AssetDatabase.GetAssetPath(a)).Concat(new[]{UnityEditor.AssetDatabase.GetAssetPath(cfg)}).ToArray(),true).Where(p=>p.StartsWith("Assets/")).OrderBy(p=>p).ToArray();
var scenes=new System.Collections.Generic.List<object>();
foreach(var path in new[]{"Assets/00.Scenes/Main/MainGame.unity","Assets/00.Scenes/Minseo/WorldSessionGame.unity"}){var s=UnityEditor.SceneManagement.EditorSceneManager.OpenPreviewScene(path);try{foreach(var root in s.GetRootGameObjects())foreach(var c in root.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true)){if(c==null)continue;var n=c.GetType().Name;if(n=="IslandInstanceSet"||n=="MapStateNet")scenes.Add(new{scene=path,type=n,path=UnityEditor.AnimationUtility.CalculateTransformPath(c.transform,null),scale=new[]{c.transform.lossyScale.x,c.transform.lossyScale.y,c.transform.lossyScale.z},json=UnityEditor.EditorJsonUtility.ToJson(c)});}}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(s);}}
return new{dependencies=deps,scenes,prefabs=assets.SelectMany(a=>a.Variants.Select((v,i)=>new{a.Id,variant=i,path=UnityEditor.AssetDatabase.GetAssetPath(v.Prefab),terrains=v.Prefab.GetComponentsInChildren<UnityEngine.Terrain>(true).Length,unsupportedRenderers=v.Prefab.GetComponentsInChildren<UnityEngine.Renderer>(true).Where(r=>!(r is UnityEngine.MeshRenderer)&&!(r is UnityEngine.ParticleSystemRenderer)).Select(r=>r.GetType().Name).ToArray(),ownCoast=v.Prefab.GetComponent<Lighthouse.World.Islands.View.IslandCoastWaveView>()!=null})).ToArray(),editor=new{playing=UnityEditor.EditorApplication.isPlaying,compiling=UnityEditor.EditorApplication.isCompiling,failed=UnityEditor.EditorUtility.scriptCompilationFailed,scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>{var s=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i);return new{s.path,s.isDirty};}).ToArray()}};
